CODE="import json,os,time,socket\nfrom pathlib import Path\npids={198924:144897054,200330:144897775,200331:144897775,200332:144897776}\ndef read(path):\n try:return Path(path).read_text()\n except (FileNotFoundError,PermissionError):return None\nv={'observed_unix':time.time(),'hostname':socket.gethostname(),'uid':os.getuid(),'slurm_job_id':os.environ.get('SLURM_JOB_ID'),'workers':{},'cgroups':{}}\nfor pid,birth in pids.items():\n root=Path('/proc')/str(pid);stat=read(root/'stat');x={'expected_start_ticks':birth}\n if stat:\n  parts=stat.rsplit(')',1)[1].split();x.update(actual_start_ticks=int(parts[19]),birth_matches=int(parts[19])==birth,state=parts[0],utime_ticks=int(parts[11]),stime_ticks=int(parts[12]))\n status=read(root/'status')\n if status:x['status']={line.split(':',1)[0]:line.split(':',1)[1].strip() for line in status.splitlines() if line.split(':',1)[0] in ['Name','Uid','VmRSS','RssAnon','RssFile','VmSwap','Threads']}\n x['io']=read(root/'io');cg=read(root/'cgroup');x['cgroup']=cg\n if cg:\n  for line in cg.splitlines():\n   _,controllers,path=line.split(':',2)\n   if controllers=='' or 'memory' in controllers.split(','):\n    folder=Path('/sys/fs/cgroup')/('memory' if controllers else '')/path.lstrip('/')\n    candidates=[folder]\n    while folder.name and folder.name!='job_750491' and folder!=folder.parent:\n     folder=folder.parent\n     if folder.name=='job_750491':candidates.append(folder);break\n    for folder in candidates:\n     if str(folder) not in v['cgroups']:\n      v['cgroups'][str(folder)]={n:read(folder/n) for n in ['memory.current','memory.max','memory.events','memory.stat','memory.swap.current','memory.swap.max','memory.usage_in_bytes','memory.limit_in_bytes','memory.failcnt','memory.memsw.usage_in_bytes','memory.pressure','io.pressure'] if (folder/n).is_file()}\n v['workers'][str(pid)]=x\ninfo=read('/proc/meminfo');v['node_meminfo']={line.split(':')[0]:line.split(':',1)[1].strip() for line in info.splitlines() if line.split(':')[0] in ['MemTotal','MemAvailable','Cached','Dirty','Writeback','SwapTotal','SwapFree']}\nv['node_memory_pressure']=read('/proc/pressure/memory');v['node_io_pressure']=read('/proc/pressure/io')\nst=os.statvfs('/data/user/jxu957/experiments');v['experiment_filesystem']={'total_bytes':st.f_blocks*st.f_frsize,'available_bytes':st.f_bavail*st.f_frsize,'scope':'shared filesystem capacity, not per-user quota'}\nv.update(training_modified=False,tensor_files_read=False,torch_imported=False,gpu_forward_triggered=False)\nprint(json.dumps(v))\n"
r=subprocess.run(['srun','--jobid=750491','--overlap','--exact','--ntasks=1','--cpus-per-task=1','--mem=1G','--gres=none','env','CUDA_VISIBLE_DEVICES=','/usr/bin/python3','-B','-c',CODE],capture_output=True,text=True,timeout=35)
